def final(eb, t, cta=SIGA):
    return {"tipo": "final", "eb": eb, "t": t, "cta": cta}


def finalv(eb, t, fala, cta=SIGA):
    """Último quadro de Reel ou live (com a fala)."""
    return {"tipo": "final", "eb": eb, "t": t, "cta": cta, "nota": "Fala: " + fala}


def q(tipo, eb, t, fala, **extra):
    """Quadro de Reel ou live: texto na tela (t, p) e a fala na nota."""
    d = {"tipo": tipo, "eb": eb, "t": t, "nota": "Fala: " + fala}
    d.update(extra)
    return d


